from astropy.io import fitsimport numpy as npimport matplotlib.pyplot as pltimport globfolder = "data/koa/HIRES/KELT-1/lev1/extracted/HI.20170702.51878"region_min = 6650region_max = 6750target_wave = 6707.8 # Doppler shift v_rad = 65.0c = 299792.458z = v_rad / c# EW integration boundsew_min = 6707.2ew_max = 6708.4def get_wave_flux_from_table(table, colnames):    upper_names = [name.upper() for name in colnames]    # Common possibilities    wave_candidates = ["WAVELENGTH", "WAVE", "LAMBDA", "WL"]    flux_candidates = ["FLUX", "SPEC", "SPECTRUM", "SCI", "COUNTS"]    wave = None    flux = None    for cand in wave_candidates:        if cand in upper_names:            wave = table[colnames[upper_names.index(cand)]]            break    for cand in flux_candidates:        if cand in upper_names:            flux = table[colnames[upper_names.index(cand)]]            break    # Fallback: use first two columns    if wave is None or flux is None:        print("  -> Could not identify standard column names, trying first two columns")        wave = table.field(0)        flux = table.field(1)    return np.array(wave), np.array(flux)files = sorted(glob.glob(f"{folder}/*.fits.gz"))print(f"Found {len(files)} files")found_any = Falsefor file in files:    print(f"\nTrying: {file}")    try:        with fits.open(file) as hdul:            if len(hdul) < 2 or hdul[1].data is None:                print("  -> No table data in HDU 1")                continue            table = hdul[1].data            colnames = table.columns.names            wave, flux = get_wave_flux_from_table(table, colnames)            # Flatten            wave = np.ravel(wave)            flux = np.ravel(flux)                        # Apply doppler correction to shift back to Rest Frame            wave = wave / (1 + z)            # Clean            mask = np.isfinite(wave) & np.isfinite(flux)            wave = wave[mask]            flux = flux[mask]            if len(wave) == 0 or len(flux) == 0:                print("  -> No finite wave/flux values")                continue                        # Check if lithium region is present            if not ((np.min(wave) < target_wave) and (np.max(wave) > target_wave)):                print("  -> This file does not cover 6708 Å")                continue            # Zoom into broad lithium region            region_mask = (wave >= region_min) & (wave <= region_max)            wave_region = wave[region_mask]            flux_region = flux[region_mask]            if len(wave_region) == 0:                print("  -> No data in lithium window")                continue            # Sort just in case wavelength is unordered            sort_idx = np.argsort(wave_region)            wave_region = wave_region[sort_idx]            flux_region = flux_region[sort_idx]            # Normalize            median_flux = np.median(flux_region)            if not np.isfinite(median_flux) or median_flux == 0:                print("  -> Bad median flux")                continue            flux_norm = flux_region / median_flux            # EQUIVALENT WIDTH CALCULATION             ew_mask = (wave_region >= ew_min) & (wave_region <= ew_max)            wave_ew = wave_region[ew_mask]            flux_ew = flux_norm[ew_mask]            if len(wave_ew) > 1:                ew = np.trapz(1 - flux_ew, wave_ew)                print(f"  -> Li Equivalent Width = {ew:.4f} Å")            else:                ew = 0.0                print("  -> Not enough points in EW window.")                        # Smooth             window = 15            if len(flux_norm) > window:                flux_smooth = np.convolve(                    flux_norm,                    np.ones(window) / window,                    mode="same"                )            else:                flux_smooth = flux_norm            # Plot            plt.figure(figsize=(8, 5))                        # Plot the smoothed line for visual clarity            plt.plot(wave_region, flux_smooth, linewidth=1.2, label="Smoothed Spectrum")                        # Shade the EW region using the exact bounds and unsmoothed flux            plt.fill_between(wave_ew, flux_ew, 1.0, color='lightblue', alpha=0.5, label="EW Integration Area")            plt.axvline(target_wave, color="red", linestyle="--", label="Li 6707.8 Å")            plt.axhline(1.0, color="gray", linestyle="--")            plt.xlim(6695, 6720) # Zoomed in tighter to see the line better            plt.ylim(min(flux_smooth) - 0.05, 1.1)            plt.xlabel("Rest Wavelength (Å)")            plt.ylabel("Normalized Flux")            plt.title(f"HIRES Lithium EW: {ew:.4f} Å\n{file.split('/')[-1]}")            plt.legend()            plt.tight_layout()            plt.show()            print("  -> Plotted successfully")            found_any = True            break    except Exception as e:        print(f"  -> Error: {e}")if not found_any:    print("\nNo file with usable lithium-region data was plotted.")